-- An administrator is usable only while both the account and its linked person
-- can authenticate. Keep the last usable/bootstrap administrator protected inside
-- the same D1 transaction, including link remaps and concurrent soft removals.
DROP TRIGGER protect_last_admin_update;
DROP TRIGGER protect_last_admin_delete;
DROP TRIGGER protect_last_admin_disable;
CREATE TRIGGER protect_last_admin_update BEFORE UPDATE OF role,personId,churchId,userId ON user_churches WHEN OLD.role='admin' AND (NEW.role<>'admin' OR NEW.churchId<>OLD.churchId OR NOT EXISTS(SELECT 1 FROM users u JOIN people p ON p.id=NEW.personId AND p.churchId=NEW.churchId WHERE u.id=NEW.userId AND u.disabled=0 AND u.passwordState='active' AND p.removed=0)) AND NOT EXISTS(SELECT 1 FROM user_churches uc JOIN users u ON u.id=uc.userId JOIN people p ON p.id=uc.personId AND p.churchId=uc.churchId WHERE uc.churchId=OLD.churchId AND uc.role='admin' AND uc.userId<>OLD.userId AND u.disabled=0 AND u.passwordState='active' AND p.removed=0) BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: last_bootstrap_administrator'); END;
CREATE TRIGGER protect_last_admin_delete BEFORE DELETE ON user_churches WHEN OLD.role='admin' AND NOT EXISTS(SELECT 1 FROM user_churches uc JOIN users u ON u.id=uc.userId JOIN people p ON p.id=uc.personId AND p.churchId=uc.churchId WHERE uc.churchId=OLD.churchId AND uc.role='admin' AND uc.userId<>OLD.userId AND u.disabled=0 AND u.passwordState='active' AND p.removed=0) BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: last_bootstrap_administrator'); END;
CREATE TRIGGER protect_last_admin_disable BEFORE UPDATE OF disabled,passwordState ON users WHEN (NEW.disabled=1 AND OLD.disabled=0 OR NEW.passwordState<>'active' AND OLD.passwordState='active') AND EXISTS(SELECT 1 FROM user_churches uc WHERE uc.userId=OLD.id AND uc.role='admin' AND NOT EXISTS(SELECT 1 FROM user_churches other JOIN users u ON u.id=other.userId JOIN people p ON p.id=other.personId AND p.churchId=other.churchId WHERE other.churchId=uc.churchId AND other.role='admin' AND other.userId<>OLD.id AND u.disabled=0 AND u.passwordState='active' AND p.removed=0)) BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: last_bootstrap_administrator'); END;
CREATE TRIGGER protect_last_admin_person BEFORE UPDATE OF removed ON people WHEN OLD.removed=0 AND NEW.removed=1 AND EXISTS(SELECT 1 FROM user_churches uc WHERE uc.churchId=OLD.churchId AND uc.personId=OLD.id AND uc.role='admin' AND NOT EXISTS(SELECT 1 FROM user_churches other JOIN users u ON u.id=other.userId JOIN people p ON p.id=other.personId AND p.churchId=other.churchId WHERE other.churchId=uc.churchId AND other.role='admin' AND other.userId<>uc.userId AND other.personId<>OLD.id AND u.disabled=0 AND u.passwordState='active' AND p.removed=0)) BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: last_bootstrap_administrator'); END;
